// AssertWideContract runs every generated check against every declared subject.
//
//	Subjects: declare each with WideSubject
//	Extend:   WideOnQuad, WideOnTriple, WideOnNoError
//	Drop:     WideWithout, by the path each check reports under
//	Unseeded: every check here runs against a fresh subject, because
//	          no method here is classified as a write.
//	          A read over an empty subject cannot tell a miss from a bug;
//	          WideSeed is what closes it.
func AssertWideContract(t *testing.T, opts ...WideOption) {
	t.Helper()
	cfg := newWideConfig(opts...)
	if len(cfg.subjects) == 0 {
		t.Fatalf("AssertWideContract was given no subject; declare one with " +
			"WideSubject(name, factory)")
	}
	for _, p := range cfg.phantoms() {
		t.Errorf("WideWithout(%q) declines nothing: no check here reports "+
			"under that path, so this suite asserts one thing more than its "+
			"author believes", p)
	}
	for _, s := range cfg.subjects {
		runWideChecks(t, cfg, s.name, s.factory, nil)
	}
}

// runWideChecks runs the whole contract against one subject.
//
// wrap is applied after the subject is built and seeded, so a wrapper is
// transparent to the seed and every failure it causes is its own.
func runWideChecks(
	t *testing.T,
	cfg *wideConfig,
	label string,
	factory func() multireturn.Wide,
	wrap func(tb testing.TB, subject multireturn.Wide) multireturn.Wide,
) {
	t.Helper()
	t.Run(label, func(t *testing.T) {
		t.Parallel()

		t.Run(wideQuad, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onQuad {
				cfg.run(t, string(suite.MethodID(wideQuad, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.ID)
				})
			}
		})

		t.Run(wideTriple, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onTriple {
				cfg.run(t, string(suite.MethodID(wideTriple, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.ID)
				})
			}
		})

		t.Run(wideNoError, func(t *testing.T) {
			t.Parallel()

			for _, c := range cfg.onNoError {
				cfg.run(t, string(suite.MethodID(wideNoError, c.name)), c.name, func(tb testing.TB) {
					c.fn(tb, cfg.subject(tb, factory, wrap), cfg.Fixture.ID)
				})
			}
		})

		// The extra bodies of checks this run was given, each reporting under its
		// own name and dropped by it.
		//
		// The plain subject only. The wrapped pass exists to prove the double
		// faithful and the per-method checks above already do that, so running one
		// through the wrapper prices the wrapper and says nothing new about the
		// subject.
		if wrap == nil {
			for _, e := range cfg.extensions {
				if cfg.declined(e.name) {
					t.Run(e.name, func(t *testing.T) {
						t.Skipf("dropped through WideWithout(%q)", e.name)
					})
					continue
				}
				t.Run(e.name, func(t *testing.T) {
					t.Parallel()
					e.run(t, label, factory, cfg)
				})
			}
		}
	})
}

